{"command":"$sourcePath = 'Script/Blueprint/Prefabs/Monsters/MainScene/BigLevel_01/LittleLevel_01/BaseMons.lua'
$root = 'Script/Blueprint/Prefabs/Monsters/MainScene'
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Get-BPDieBlock {
    param([string]$Text)
    $lines = [System.Text.RegularExpressions.Regex]::Split($Text, "(?<=`n)")
    $start = -1
    for ($i = 0; $i -lt $lines.Length; $i++) {
        if ($lines[$i] -match '^function\s+BaseMons:BPDie\(') {
            $start = $i
            break
        }
    }
    if ($start -lt 0) { throw 'BPDie start not found' }

    $depth = 0
    for ($i = $start; $i -lt $lines.Length; $i++) {
        $code = $lines[$i] -replace '--.*$', ''
        if ($code -match '^\s*function\b') { $depth++ }
        if ($code -match '\bthen\s*$') { $depth++ }
        if ($code -match '^\s*end\s*$') { $depth-- }
        if ($depth -eq 0 -and $i -gt $start) {
            return -join $lines[$start..$i]
        }
    }
    throw 'BPDie end not found'
}

function Replace-BPDieBlock {
    param([string]$Text, [string]$NewBlock)
    $lines = [System.Text.RegularExpressions.Regex]::Split($Text, "(?<=`n)")
    $start = -1
    for ($i = 0; $i -lt $lines.Length; $i++) {
        if ($lines[$i] -match '^function\s+BaseMons:BPDie\(') {
            $start = $i
            break
        }
    }
    if ($start -lt 0) { throw 'BPDie start not found' }

    $depth = 0
    $end = -1
    for ($i = $start; $i -lt $lines.Length; $i++) {
        $code = $lines[$i] -replace '--.*$', ''
        if ($code -match '^\s*function\b') { $depth++ }
        if ($code -match '\bthen\s*$') { $depth++ }
        if ($code -match '^\s*end\s*$') { $depth-- }
        if ($depth -eq 0 -and $i -gt $start) {
            $end = $i
            break
        }
    }
    if ($end -lt 0) { throw 'BPDie end not found' }

    $before = if ($start -gt 0) { -join $lines[0..($start - 1)] } else { '' }
    $after = if ($end + 1 -lt $lines.Length) { -join $lines[($end + 1)..($lines.Length - 1)] } else { '' }
    return $before + $NewBlock + $after
}

$sourceText = [System.IO.File]::ReadAllText((Resolve-Path $sourcePath), [System.Text.Encoding]::UTF8)
$newBlock = Get-BPDieBlock $sourceText

$files = Get-ChildItem -Path $root -Recurse -Filter 'BaseMons.lua' | Where-Object { $_.FullName -ne (Resolve-Path $sourcePath).Path }
$changed = 0
foreach ($file in $files) {
    $text = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
    $updated = Replace-BPDieBlock $text $newBlock
    if ($updated -ne $text) {
        [System.IO.File]::WriteAllText($file.FullName, $updated, $utf8NoBom)
        $changed++
    }
}
Write-Output "Copied BPDie block to $changed files."","timeout_ms":10000,"workdir":"C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects\Douluo"}

